public class OrderServiceTest {
    private OrderService service;
    private OrderRepository mockRepository;
    private NotificationService mockNotifier;

    @BeforeEach
    void setup() {
        // Create mocks without Spring container
        mockRepository = mock(OrderRepository.class);
        mockNotifier = mock(NotificationService.class);

        // Inject mocks via constructor
        service = new OrderService(mockRepository, mockNotifier);
    }

    @Test
    void createOrder_shouldSaveAndNotify() {
        var request = new OrderRequest(123L, List.of("item1"));

        service.createOrder(request);

        verify(mockRepository).save(any(Order.class));  // No database needed
        verify(mockNotifier).sendConfirmation(any(Order.class));
    }
}
