interface Notifier { void send(String msg); }

@Component @Primary           // the default when no qualifier is given
class EmailNotifier implements Notifier { public void send(String m) {} }

@Component("smsNotifier")
class SmsNotifier implements Notifier { public void send(String m) {} }

@Service
class AlertService {
    private final Notifier notifier;
    // No qualifier -> Spring injects the @Primary EmailNotifier
    AlertService(Notifier notifier) { this.notifier = notifier; }
}

@Service
class OtpService {
    private final Notifier notifier;
    // @Qualifier overrides @Primary -> injects SmsNotifier
    OtpService(@Qualifier("smsNotifier") Notifier notifier) {
        this.notifier = notifier;
    }
}
