// PROBLEM: Circular dependency with constructor injection
@Service
class OrderService {
    private final PaymentService paymentService;

    OrderService(PaymentService paymentService) {
        this.paymentService = paymentService; // needs PaymentService
    }
}

@Service
class PaymentService {
    private final OrderService orderService;

    PaymentService(OrderService orderService) {
        this.orderService = orderService; // needs OrderService - circular!
    }
}

// WORKAROUND (not ideal): Using @Lazy
@Service
class OrderService {
    private final PaymentService paymentService;

    OrderService(@Lazy PaymentService paymentService) { // delays injection
        this.paymentService = paymentService;
    }
}

// PROPER FIX: Extract shared logic to break the cycle
@Service
class OrderService {
    private final PricingService pricingService; // new third service

    OrderService(PricingService pricingService) {
        this.pricingService = pricingService;
    }
}

@Service
class PaymentService {
    private final PricingService pricingService; // both depend on shared service

    PaymentService(PricingService pricingService) {
        this.pricingService = pricingService;
    }
}

@Service
class PricingService {
    // Contains shared logic, no circular dependency
    public BigDecimal calculateTotal(Order order) {
        return order.getItems().stream()
            .map(Item::getPrice)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
