// Abstraction: high-level module depends on this interface
interface OrderRepository {
    Optional<Order> findById(Long id);
    void save(Order order);
}

// Concrete implementation 1: JPA-based
@Repository
class JpaOrderRepository implements OrderRepository {
    private final EntityManager em;

    JpaOrderRepository(EntityManager em) {
        this.em = em;
    }

    public Optional<Order> findById(Long id) {
        return Optional.ofNullable(em.find(Order.class, id));
    }

    public void save(Order order) {
        em.persist(order);
    }
}

// Concrete implementation 2: in-memory for testing
@Repository
@Profile("test")
class InMemoryOrderRepository implements OrderRepository {
    private final Map<Long, Order> store = new HashMap<>();

    public Optional<Order> findById(Long id) {
        return Optional.ofNullable(store.get(id));
    }

    public void save(Order order) {
        store.put(order.id(), order);
    }
}

// High-level module: depends on abstraction, not concrete class
@Service
class OrderService {
    private final OrderRepository repository; // interface, not JpaOrderRepository

    OrderService(OrderRepository repository) { // Spring injects implementation
        this.repository = repository;
    }

    public void processOrder(Long orderId) {
        var order = repository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(orderId));
        // business logic here - doesn't care about DB vs in-memory
    }
}
